import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Dal discreto al continuo","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/le/leba.md","filePath":"lezioni/l_calcolo-delle-probabilita/le/leba.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/le/leba.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="dal-discreto-al-continuo" tabindex="-1">Dal discreto al continuo <a class="header-anchor" href="#dal-discreto-al-continuo" aria-label="Permalink to “Dal discreto al continuo”">​</a></h1><p>Esistono vari tipi di problemi in cui l&#39;insieme dei valori possibili è continuo, cioè abbiamo un numero infinito di probabilità per tutti i valori compresi in un intervallo in corrispondenza biunivoca con un intervallo della Retta Reale.</p><p>Esempi:</p><ul><li><strong>la probabilità di caduta di un satellite su una zona dell&#39;Europa</strong> So solamente che cadrà in una certa zona con probabilità <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi></mrow><annotation encoding="application/x-tex">p</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span>, ma non posso indicare un punto o un numero finito di punti in cui può cadere.</li><li><strong>l&#39;usura di un cilindro ruotante in un meccanismo</strong> Posso indicare il raggio massimo ed il raggio minimo che mi permette di usarlo, ma non posso suddividere la differenza dei raggi in un numero finito di punti.</li><li><strong>La probabilità di morire di una persona di sesso maschile di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>50</mn></mrow><annotation encoding="application/x-tex">50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">50</span></span></span></span> anni da oggi al <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2070</mn></mrow><annotation encoding="application/x-tex">2070</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2070</span></span></span></span></strong> Serve per calcolare le tabelle assicurative, ma non posso indicare il valore preciso della probabilità di morte istante per istante.</li></ul><p>Quelli sopra sono tutti esempi di probabilità continua; in alcuni casi si può ovviare, come nel caso delle assicurazioni, dividendo l&#39;intervallo in anni, però è un&#39;approssimazione: la probabilità di morte di una persona a gennaio sarà diversa dalla probabilità per la stessa persona a dicembre dello stesso anno.</p><p>Consideriamo ancora la caduta di un oggetto su un piano determinato: come posso esprimere la probabilità di impatto in un punto se un punto non ha dimensione? Allora dovrò sostituire al concetto di punto il solito concetto di intervallo per poter trovare una probabilità effettiva: è lo stesso ragionamento che ci ha portato a costruire l&#39;analisi matematica basandola sul concetto di intervallo; Se considero un intervallo, anche se infinitesimo, allora per esso potrò parlare della probabilità di impatto con l&#39;oggetto che cade.</p><p>Per sapere come comportarci intuitivamente riferiamoci ad un esempio classico: <strong>lanciando una moneta ho due possibilità: o testa o croce entrambe con probabilità <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac></mrow><annotation encoding="application/x-tex">p = \\frac{1}{2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.1901em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></strong> Abbiamo già studiato questo caso e visto la distribuzione di questo fenomeno (vedi l&#39;esempio). Se aumentiamo il numero delle prove avremo che al posto dei rettangoli avremo dei rettangoli sempre più snelli sino ad arrivare a basi infinitesime e quindi ad avere, per i valori delle probabilità, una curva indistinguibile da una curva continua.</p><p>Dovremo quindi di utilizzare l&#39;analisi matematica e lo studio di funzioni, inoltre, siccome le probabilità saranno legate alle aree di parti delle curve, dovremo conoscere bene soprattutto il calcolo degli integrali definiti.</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};